mapper.insert:
INSERT INTO sys_dict_type (
    dict_code, dict_name, status, remark, created_by, updated_by
) VALUES (
    #{dictCode}, #{dictName}, #{status}, #{remark}, #{createdBy}, #{updatedBy}
)

mapper.update:
UPDATE sys_dict_type
SET status = 0, deleted_at = #{deletedAt}, updated_by = #{updatedBy}
WHERE id = #{id} AND deleted_at = 0

mapper.insert:
INSERT INTO sys_dict_item (
    dict_type_id, item_value, item_label, sort_order, status, remark,
    created_by, updated_by
) VALUES (
    #{dictTypeId}, #{itemValue}, #{itemLabel}, #{sortOrder}, #{status}, #{remark},
    #{createdBy}, #{updatedBy}
)

mapper.update:
UPDATE sys_dict_item
SET status = 0, deleted_at = #{deletedAt}, updated_by = #{updatedBy}
WHERE id = #{id} AND deleted_at = 0

UPDATE sys_dict_item
SET status = 0, deleted_at = #{deletedAt}, updated_by = #{updatedBy}
WHERE dict_type_id = #{dictTypeId} AND deleted_at = 0
